  function setMode(mode){if(recorder?.state==='recording')return;draft.captureType=mode;draft.domain=['idea','method'].includes(mode)?'knowledge':'practice';if(['idea','method'].includes(mode)&&draft.pairing?.kind==='session')draft.pairing=null;uiStage='capture';renderMode();renderTransfer();scheduleSave('Capture-Modus wird gespeichert …');updateProductUI()}
  function renderMode(){const mode=draft.captureType||'dictation',idea=mode==='idea',method=mode==='method';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#audioSection').hidden=mode==='note';$('#inkSection').hidden=mode==='dictation';$('#noteSection').hidden=false;$('#consentWrap').hidden=mode!=='session';if($('#ideaMetaSection'))$('#ideaMetaSection').hidden=!idea;$('#methodMetaSection').hidden=!method;if($('#workTitle'))$('#workTitle').textContent=mode==='session'?'Sitzung aufnehmen':mode==='note'?'Notiz':idea?'Idee festhalten':method?'Übung festhalten':'Diktat';if($('#workSubtitle'))$('#workSubtitle').textContent=mode==='session'?'Audio und Handschrift · lokal gesichert':mode==='note'?'Text, Handschrift oder Foto · lokal gesichert':idea?'Geistesblitz, Fundstück oder Screenshot · lokal gesichert':method?'Audio, Text, Foto oder Link · lokal gesichert':'Kurze Nachbesprechung · lokal gesichert';if($('#recordHelp'))$('#recordHelp').textContent=idea?'Sprich deinen Gedanken ein – Whisper transkribiert ihn später lokal im Knowledge Hub.':mode==='session'?'Audio wird fortlaufend lokal gesichert. Du kannst gleichzeitig mitschreiben.':'Audio wird fortlaufend lokal gesichert.';const details=$('#noteDetails');if(details)details.open=mode==='note'||idea||method;if($('#ideaSourceType'))$('#ideaSourceType').value=draft.ideaSourceType||'own';if($('#ideaSourceUrl'))$('#ideaSourceUrl').value=draft.ideaSourceUrl||'';$('#methodSourceType').value=draft.methodSourceType||'';$('#methodSourceDescription').value=draft.methodSourceDescription||'';$('#methodSourceUrl').value=draft.methodSourceUrl||'';const photo=$('#photoInput');if(photo){if(idea||method)photo.removeAttribute('capture');else photo.setAttribute('capture','environment')}if($('#photoButtonLabel'))$('#photoButtonLabel').textContent=idea||method?'Screenshot / Bild hinzufügen':'Foto hinzufügen';updateRecordStartState();updateProductUI()}
  function updateRecordStartState(){const needsConsent=draft?.captureType==='session';$('#recordStart').disabled=!!recorder||needsConsent&&!$('#consentConfirmed').checked}
  function renderPhotos(){$('#photoPreview').innerHTML=draft.photos.length?draft.photos.map((photo,index)=>`<article class="media-item"><img src="data:${esc(photo.mime)};base64,${photo.dataBase64}" alt="Foto ${index+1}"><div class="media-copy"><strong>${esc(photo.name||'Foto '+(index+1))}</strong><small>Foto ${index+1} von ${draft.photos.length}</small></div><button class="danger" data-photo-delete="${index}" type="button">Entfernen</button></article>`).join(''):'<p class="help">Noch keine Fotos hinzugefügt.</p>';document.querySelectorAll('[data-photo-delete]').forEach(button=>button.onclick=()=>{draft.photos.splice(Number(button.dataset.photoDelete),1);renderPhotos();scheduleSave();updateProductUI()})}
  function audioBlob(item){return new Blob([from64(item.dataBase64)],{type:item.mime||'audio/webm'})}
  function renderAudio(){audioUrls.forEach(URL.revokeObjectURL);audioUrls=[];const host=$('#audioList');if(!draft.audio.length){host.innerHTML='<p class="help">Noch keine Aufnahmen vorhanden.</p>';return}host.innerHTML='';draft.audio.forEach((item,index)=>{const url=URL.createObjectURL(audioBlob(item));audioUrls.push(url);const article=document.createElement('article');article.className='media-item';article.innerHTML=`<div class="media-copy"><strong>${draft.captureType==='session'?'Sitzungsaufnahme':'Aufnahme'} ${index+1}${item.recovered?' · wiederhergestellt':''}</strong><small>${formatTime(Number(item.durationSeconds||0))} · lokal gespeichert</small></div><audio controls src="${url}"></audio><button class="danger" type="button">Entfernen</button>`;article.querySelector('button').onclick=()=>{if(confirm('Diese lokal gespeicherte Aufnahme wirklich entfernen?')){draft.audio.splice(index,1);renderAudio();scheduleSave()}};host.appendChild(article)});updateProductUI()}
  function page(){return draft.inkPages[activePage]}
  function renderInkPages(){activePage=Math.max(0,Math.min(activePage,draft.inkPages.length-1));$('#inkPageSelect').innerHTML=draft.inkPages.map((item,index)=>`<option value="${index}">Seite ${index+1}</option>`).join('');$('#inkPageSelect').value=String(activePage);$('#inkPageState').textContent=`Seite ${activePage+1} von ${draft.inkPages.length}`;$('#inkPrev').disabled=activePage===0;$('#inkNext').disabled=activePage===draft.inkPages.length-1;$('#inkDelete').disabled=draft.inkPages.length===1;drawInk();updateProductUI()}
  function einkOptimized(){return draft?.deviceType==='boox'||document.body.classList.contains('ink')||document.body.classList.contains('eink-device')}
  function applyDeviceProfile(){const boox=draft?.deviceType==='boox'||/boox|onyx/i.test(navigator.userAgent||'');document.body.classList.toggle('eink-device',boox);const manual=localStorage.getItem(EINK_KEY)==='1';document.body.classList.toggle('ink',manual);if($('#inkMode'))$('#inkMode').textContent=manual?'E‑Ink-Modus ✓':'E‑Ink-Modus';if($('#deviceType')&&boox&&$('#deviceType').value!=='boox')$('#deviceType').value='boox'}
  function resizeCanvas(){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=einkOptimized()?1:Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(rect.width*ratio));canvas.height=Math.max(1,Math.floor(rect.height*ratio));ctx.setTransform(ratio,0,0,ratio,0,0);drawInk()}
  function prepareInkContext(){ctx.lineWidth=einkOptimized()?2.15:2;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#111'}
  function drawInk(){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;ctx.clearRect(0,0,rect.width,rect.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,rect.width,rect.height);prepareInkContext();for(const stroke of page()?.strokes||[]){if(!stroke.length)continue;ctx.beginPath();ctx.moveTo(stroke[0].x*rect.width,stroke[0].y*rect.height);for(const point of stroke.slice(1))ctx.lineTo(point.x*rect.width,point.y*rect.height);if(stroke.length===1)ctx.lineTo(stroke[0].x*rect.width+.2,stroke[0].y*rect.height+.2);ctx.stroke()}}
