  async function compressPhoto(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),work=document.createElement('canvas');work.width=Math.max(1,Math.round(bitmap.width*scale));work.height=Math.max(1,Math.round(bitmap.height*scale));work.getContext('2d').drawImage(bitmap,0,0,work.width,work.height);bitmap.close?.();const blob=await new Promise(resolve=>work.toBlob(resolve,'image/jpeg',.8));return{mime:'image/jpeg',name:(file.name||'foto').replace(/\.[^.]+$/,'')+'.jpg',dataBase64:bytes64(new Uint8Array(await blob.arrayBuffer())),createdAt:now()}}
  function recorderMime(){return['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(type=>window.MediaRecorder?.isTypeSupported?.(type))||''}
  function chunkKey(captureId,recordingId,sequence){return`${captureId}|${recordingId}|${String(sequence).padStart(6,'0')}`}
