      stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});const mime=recorderMime(),recordingId=uid();chunkSequence=0;chunkSaveChain=Promise.resolve();recordStarted=Date.now();draft.pendingRecording={id:recordingId,startedAt:now(),mime:mime||'audio/webm',captureType:draft.captureType};await saveNow();
      recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);
