  function pairingFrom(value){const url=new URL(String(value).trim(),location.href),relay=url.searchParams.get('relay')||'',token=url.searchParams.get('token')||'',key=url.searchParams.get('key')||'';if(!/^[a-f0-9]{32}$/i.test(relay)||token.length<32||key.length<32)throw new Error('Dieser QR-Code enthält keine vollständige Sitzungs-Verbindung.');return{relay,token,key,pairedAt:now(),kind:'session',sessionId:url.searchParams.get('session')||'',sessionDate:url.searchParams.get('sessionDate')||'',owner:url.searchParams.get('owner')||''}}
