  function knowledgeCaptureType(target){if(!['idea','method'].includes(target.captureType))return target.captureType;const a=(target.audio||[]).length>0,t=!!String(target.noteText||'').trim(),p=(target.photos||[]).length>0,i=(target.inkPages||[]).some(page=>(page.strokes||[]).length),u=!!String(target.captureType==='method'?target.methodSourceUrl:target.ideaSourceUrl||'').trim(),n=(target.photos||[]).map(x=>String(x.name||'').toLowerCase()).join(' '),source=String(target.ideaSourceType||'');const count=[a,t,p,i].filter(Boolean).length;if(count>1)return'mixed';if(a)return'audio';if(t)return'text';if(i)return'handwriting';if(p)return(/screenshot|screen.?shot|bildschirm|capture/.test(n)||['reddit','youtube','web'].includes(source))?'screenshot':'image';if(u)return'link';return'other'}
