    const x=await jsonPost('/capture-transfer/create-access',{pairId:accessPairing.pairId,accessToken:accessPairing.token,routingScope:workspace?'workspace':'personal',captureKind:draft.captureType});
    draft.pairing={relay:x.relay,token:x.token,key:workspace?accessPairing.workspaceKey:accessPairing.key,workspaceKeyId:workspace?accessPairing.workspaceKeyId||'':'',pairedAt:now(),kind:'inbox',generic:true,accessPairId:accessPairing.pairId,owner:accessPairing.owner||'',userId:accessPairing.userId||'',practiceId:accessPairing.practiceId||'',practitionerId:accessPairing.practitionerId||'',vaultId:accessPairing.vaultId||'',routingScope:workspace?'workspace':'personal'};
