  function openPairCodeDialog(){const d=$('#pairCodeDialog');if(!d)return;$('#pairCodeInput').value='';$('#pairCodeState').textContent='Den Code findest du im CRM unter „Gerät verbinden“.';$('#pairCodeState').className='save-state';d.showModal();setTimeout(()=>$('#pairCodeInput')?.focus(),80)}
